#include <vector>
#include <cstddef>
#include <limits>
#include <omp.h>

size_t findFirstEven(std::vector<int> const& x) {
    const size_t n = x.size();
    const size_t NOT_FOUND = std::numeric_limits<size_t>::max();

    size_t best = NOT_FOUND;

    #pragma omp parallel
    {
        size_t local_best = NOT_FOUND;

        #pragma omp for nowait
        for (size_t i = 0; i < n; ++i) {
            if ((x[i] & 1) == 0) {
                if (i < local_best) local_best = i;
            }
        }

        #pragma omp critical
        {
            if (local_best < best) best = local_best;
        }
    }

    return best;
}
